<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#080a0f">
<title>FAIZAN ANSARI WEB2APK</title>
<style>
:root{--bg:#080a0f;--card:#10141c;--card2:#0c1017;--line:#232b38;--text:#f7f8fb;--muted:#8d98aa;--gold:#e1b052;--gold2:#f4cf7a;--green:#4ed39a;--red:#ff6675}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}body{background:radial-gradient(circle at 15% 0,rgba(225,176,82,.1),transparent 32rem),radial-gradient(circle at 100% 15%,rgba(87,108,255,.07),transparent 28rem)}button,input{font:inherit}.wrap{width:min(920px,calc(100% - 24px));margin:auto;padding:38px 0 20px}.top{display:flex;align-items:center;gap:15px;margin-bottom:22px}.logo{width:64px;height:64px;border-radius:50%;flex-shrink:0;overflow:hidden;background:#0b0f16;border:1px solid rgba(78,211,154,.4);box-shadow:0 14px 34px rgba(30,110,255,.22),0 0 0 1px rgba(255,255,255,.03) inset}.logo img{width:100%;height:100%;object-fit:cover;display:block}.title{font-size:clamp(30px,7vw,48px);line-height:1;margin:0;letter-spacing:-.05em;background:linear-gradient(135deg,#f7f8fb 15%,#bcd4ff 55%,#4ed39a 100%);-webkit-background-clip:text;background-clip:text;color:transparent}.sub{font-size:12px;color:var(--muted);margin-top:7px}.card,.progress,.result,.error{background:linear-gradient(145deg,rgba(17,21,29,.98),rgba(10,13,19,.98));border:1px solid var(--line);border-radius:20px;margin-bottom:14px;box-shadow:0 20px 65px rgba(0,0,0,.28)}.card{padding:21px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:17px}.head-left{display:flex;align-items:center;gap:10px}.num{width:29px;height:29px;display:grid;place-items:center;border-radius:9px;background:rgba(225,176,82,.1);border:1px solid rgba(225,176,82,.2);color:var(--gold2);font-size:9px;font-weight:900}.head h2{font-size:16px;margin:0}.hint{font-size:10px;color:var(--muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{display:flex;flex-direction:column;gap:7px}.wide{grid-column:1/-1}.field span,.url span{font-size:10px;color:#aeb7c5;font-weight:800}input{height:47px;border-radius:11px;border:1px solid var(--line);background:#090d13;color:var(--text);padding:0 13px;outline:none;transition:.2s}input:focus{border-color:rgba(225,176,82,.65);box-shadow:0 0 0 3px rgba(225,176,82,.08)}input::placeholder{color:#535e6e}.icons{display:grid;grid-template-columns:1fr 28px 1.2fr 100px;gap:12px;align-items:center}.upload{height:125px;border:1px dashed #394353;border-radius:15px;background:#090d13;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;cursor:pointer}.upload:hover{border-color:rgba(225,176,82,.65)}.upload input{display:none}.upload b{font-size:24px;color:var(--gold2)}.upload strong{font-size:12px;margin-top:3px}.upload small,.url small{font-size:9px;color:var(--muted);margin-top:4px}.or{text-align:center;font-size:9px;color:#5f6978;font-weight:900}.url{display:flex;flex-direction:column;gap:7px}.url input{height:47px}.preview{height:125px;border:1px solid var(--line);border-radius:15px;background:#090d13;display:grid;place-items:center;overflow:hidden}.preview span{font-size:9px;letter-spacing:.16em;color:#4e5969;font-weight:900}.preview img{width:78px;height:78px;object-fit:cover;border-radius:17px}.generate{width:100%;height:57px;border:0;border-radius:14px;background:linear-gradient(135deg,var(--gold2),var(--gold));color:#171106;font-size:13px;font-weight:950;cursor:pointer;box-shadow:0 15px 38px rgba(225,176,82,.15);transition:.2s}.generate:hover{transform:translateY(-1px)}.generate:disabled{opacity:.6;cursor:not-allowed;transform:none}.progress{padding:19px;display:grid;grid-template-columns:auto 1fr;gap:11px;align-items:center}.spinner{width:28px;height:28px;border:3px solid #29313e;border-top-color:var(--gold2);border-radius:50%;animation:spin .75s linear infinite}.status strong{display:block;font-size:13px}.status span{display:block;color:var(--muted);font-size:10px;margin-top:4px}.bar{grid-column:1/-1;height:5px;background:#222936;border-radius:99px;overflow:hidden;margin-top:3px}.bar i{display:block;height:100%;width:3%;background:linear-gradient(90deg,var(--gold),var(--gold2));border-radius:99px;transition:width .45s}.result{padding:17px;display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;border-color:rgba(78,211,154,.25)}.check{width:39px;height:39px;border-radius:12px;background:rgba(78,211,154,.1);color:var(--green);display:grid;place-items:center;font-weight:950}.result h2{font-size:14px;margin:0 0 4px}.result p{font-size:10px;color:var(--muted);margin:0}.download{display:inline-flex;padding:11px 15px;border-radius:10px;background:var(--green);color:#06130c;text-decoration:none;font-size:11px;font-weight:950}.error{padding:17px;border-color:rgba(255,102,117,.25)}.error strong{font-size:13px;color:#ff8995;display:block}.error p{font-size:10px;color:var(--muted);margin:6px 0 12px}.retry{border:1px solid var(--line);background:#111721;color:var(--text);border-radius:10px;padding:9px 13px;font-size:10px;font-weight:800;cursor:pointer}.watermark{text-align:center;color:#4c5665;font-size:9px;padding:23px 0 3px}.hide{display:none!important}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:700px){.wrap{padding-top:25px}.logo{width:50px;height:50px;border-radius:50%}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.icons{grid-template-columns:1fr}.or{padding:1px}.preview{height:105px}.result{grid-template-columns:auto 1fr}.download{grid-column:1/-1;justify-content:center}.error .retry{width:100%}}
</style>
</head>
<body>
<main class="wrap">
<header class="top"><div class="logo"><img src="data:image/png;base64,
